# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SAKİN MİM\'İN (مْ) ÜÇ HÂLİ VE TECVİT KURALLARI (KK.9.2.6)</text>\n  <rect x="20" y="45" width="210" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">1. İDGAM-I MİSLEYN MEAL-GUNNE</text>\n  <text x="125" y="92" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">مْ + م (Mim + Mim)</text>\n  <text x="32" y="116" font-size="10.5" fill="#1e3a8a">• Sakin mim\'den (مْ) sonra</text>\n  <text x="32" y="132" font-size="10.5" fill="#1e3a8a">harekeli bir mim (م) gelirse</text>\n  <text x="32" y="148" font-size="10.5" fill="#1e3a8a">iki mim birleştirilerek</text>\n  <text x="32" y="164" font-size="10.5" font-weight="bold" fill="#b91c1c">gunneli ve şeddeli okunur.</text>\n  <text x="32" y="192" font-size="11" font-weight="bold" fill="#1e40af">Örnek: لَهُمْ مَا يَشَاءُونَ</text>\n  <text x="32" y="212" font-size="11" font-weight="bold" fill="#1e40af">Örnek: أَطْعَمَهُمْ مِنْ جُوعٍ</text>\n  <rect x="245" y="45" width="210" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">2. İHFA-İ ŞEFEVÎ (DUDAK İHFASI)</text>\n  <text x="350" y="92" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">مْ + ب (Mim + Be)</text>\n  <text x="257" y="116" font-size="10.5" fill="#14532d">• Sakin mim\'den (مْ) sonra</text>\n  <text x="257" y="132" font-size="10.5" fill="#14532d">be (ب) harfi gelirse dudaklar</text>\n  <text x="257" y="148" font-size="10.5" fill="#14532d">hafifçe değdirilip mim sesi</text>\n  <text x="257" y="164" font-size="10.5" font-weight="bold" fill="#15803d">gunneli olarak gizlenir.</text>\n  <text x="257" y="192" font-size="11" font-weight="bold" fill="#14532d">Örnek: تَرْمِيهِمْ بِحِجَارَةٍ</text>\n  <text x="257" y="212" font-size="11" font-weight="bold" fill="#14532d">Örnek: وَهُمْ بِالْآخِرَةِ</text>\n  <rect x="470" y="45" width="210" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#b45309">3. İZHAR-I ŞEFEVÎ (DUDAK İZHARI)</text>\n  <text x="575" y="92" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">مْ + Diğer 26 Harf</text>\n  <text x="482" y="116" font-size="10.5" fill="#78350f">• Sakin mim\'den (مْ) sonra</text>\n  <text x="482" y="132" font-size="10.5" fill="#78350f">م ve ب dışındaki 26 harften</text>\n  <text x="482" y="148" font-size="10.5" fill="#78350f">biri gelirse mim harfi gunnesiz</text>\n  <text x="482" y="164" font-size="10.5" font-weight="bold" fill="#b45309">ve açıkça (net) okunur.</text>\n  <text x="482" y="192" font-size="11" font-weight="bold" fill="#78350f">Örnek: لَمْ يَلِدْ وَلَمْ يُولَدْ</text>\n  <text x="482" y="212" font-size="11" font-weight="bold" fill="#78350f">Örnek: أَلَمْ تَرَ · هُمْ فِيهَا</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">MAhREÇ VE SIFAT BİRLİKTELİĞİNE GÖRE İDGAM ÇEŞİTLERİ (KK.9.2.6)</text>\n  <rect x="20" y="45" width="210" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. İDGAM-I MİSLEYN</text>\n  <text x="125" y="88" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">(Aynı Harflerin Birleşmesi)</text>\n  <text x="32" y="112" font-size="10" fill="#1e3a8a">• Mahreçleri ve sıfatları</text>\n  <text x="32" y="126" font-size="10" fill="#1e3a8a">BİREBİR AYNI olan iki harfin</text>\n  <text x="32" y="140" font-size="10" fill="#1e3a8a">(birincisi sakin, ikincisi harekeli)</text>\n  <text x="32" y="154" font-size="10" fill="#1e3a8a">şeddeli okunmasıdır.</text>\n  <text x="32" y="178" font-size="10" font-weight="bold" fill="#b91c1c">• ن ve م harflerinde gunneli:</text>\n  <text x="38" y="194" font-size="10" fill="#1e40af">مِنْ نِعْمَةٍ · لَهُمْ مَا</text>\n  <text x="32" y="212" font-size="10" font-weight="bold" fill="#15803d">• Diğer harflerde gunnesiz:</text>\n  <text x="38" y="228" font-size="10" fill="#1e40af">اِضْرِبْ بِعَصَاكَ · قَدْ دَخَلُوا</text>\n  <rect x="245" y="45" width="210" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">2. İDGAM-I MÜTECANİSEYN</text>\n  <text x="350" y="88" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#6b21a8">(Aynı Mahreç, Farklı Sıfat)</text>\n  <text x="257" y="112" font-size="10" fill="#581c87">• Mahreçleri (çıkış yerleri)</text>\n  <text x="257" y="126" font-size="10" fill="#581c87">AYNI, sıfatları farklı olan</text>\n  <text x="257" y="140" font-size="10" fill="#581c87">üç harf grubunda olur:</text>\n  <text x="257" y="162" font-size="10" font-weight="bold" fill="#6b21a8">1) ط - د - ت grubu:</text>\n  <text x="263" y="176" font-size="10" fill="#581c87">قَدْ تَبَيَّنَ · عَبَدْتُمْ · بَسَطْتَ</text>\n  <text x="257" y="196" font-size="10" font-weight="bold" fill="#6b21a8">2) ظ - ذ - ث grubu: إِذْ ظَلَمُوا</text>\n  <text x="257" y="216" font-size="10" font-weight="bold" fill="#6b21a8">3) ب - م grubu: يَا بُنَيَّ ارْكَبْ مَعَنَا</text>\n  <rect x="470" y="45" width="210" height="195" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">3. İDGAM-I MÜTEKARİBEYN</text>\n  <text x="575" y="88" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#881337">(Yakın Mahreç ve Sıfat)</text>\n  <text x="482" y="112" font-size="10" fill="#9f1239">• Mahreçleri veya sıfatları</text>\n  <text x="482" y="126" font-size="10" fill="#9f1239">birbirine YAKIN olan iki</text>\n  <text x="482" y="140" font-size="10" fill="#9f1239">harfin birleştirilmesidir:</text>\n  <text x="482" y="164" font-size="10.5" font-weight="bold" fill="#881337">1) ل ve ر harfleri (لْ + ر):</text>\n  <text x="488" y="182" font-size="10.5" fill="#9f1239">قُلْ رَبِّ · بَلْ رَفَعَهُ اللّٰهُ</text>\n  <text x="482" y="206" font-size="10.5" font-weight="bold" fill="#881337">2) ق ve ك harfleri (قْ + ك):</text>\n  <text x="488" y="224" font-size="10.5" fill="#9f1239">أَلَمْ نَخْلُقْكُمْ</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">RA (ر) HARFİNİN OKUNUŞ HÂLLERİ: KALIN (TEFHİM) VE İNCE (TERKİK)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. KALIN (TEFHİM) OKUNDUĞU DURUMLAR</text>\n  <text x="35" y="96" font-size="10.5" font-weight="bold" fill="#1e3a8a">• Ra harfinin harekesi üstün (رَ) veya ötre (رُ) ise:</text>\n  <text x="43" y="114" font-size="10.5" fill="#1d4ed8">رَبَّنَا · رَحْمَةٌ · رُزِقْنَا · كَفَرُوا</text>\n  <text x="35" y="140" font-size="10.5" font-weight="bold" fill="#1e3a8a">• Ra sakin (رْ) olup önceki harf üstün veya ötre ise:</text>\n  <text x="43" y="158" font-size="10.5" fill="#1d4ed8">مَرْيَمَ · يَرْزُقُ · قُرْآنٌ · الْعَرْشِ</text>\n  <text x="35" y="184" font-size="10.5" font-weight="bold" fill="#1e3a8a">• Sakin Ra\'dan sonra kalın (isti\'lâ) harf gelirse:</text>\n  <text x="43" y="202" font-size="10.5" fill="#1d4ed8">مِرْصَادًا · قِرْطَاسٍ · فِرْقَةٍ</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. İNCE (TERKİK) OKUNDUĞU DURUMLAR</text>\n  <text x="375" y="96" font-size="10.5" font-weight="bold" fill="#14532d">• Ra harfinin harekesi esre / kesra (رِ) ise:</text>\n  <text x="383" y="114" font-size="10.5" fill="#166534">رِزْقًا · رِجَالٌ · كَرِيمٌ · الْفَجْرِ</text>\n  <text x="375" y="140" font-size="10.5" font-weight="bold" fill="#14532d">• Ra sakin (رْ) olup önceki harf asli esreli ise:</text>\n  <text x="383" y="158" font-size="10.5" fill="#166534">فِرْعَوْنَ · شِرْعَةً · مِرْيَةٍ · وَاسْتَغْفِرْ</text>\n  <text x="375" y="184" font-size="10.5" font-weight="bold" fill="#14532d">• Durak (vakıf) sebebiyle sakin olan Ra\'dan önce</text>\n  <text x="383" y="202" font-size="10.5" fill="#166534">sakin yâ (يْ) harfi varsa: قَدِيرٌ ← قَدِيرْ · خَبِيرْ · خَيْرْ</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
